package com.gymflow.app;
import android.app.AlertDialog; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import org.json.*;
public class MembersActivity extends AppCompatActivity{
 private LinearLayout list;
 @Override protected void onCreate(Bundle b){super.onCreate(b);ScrollView s=new ScrollView(this);LinearLayout r=Ui.page(this);s.addView(r);Ui.backHeader(this,r,"Socios");r.addView(Ui.subtitle(this,"Socios guardados online en tu gimnasio."));Button add=Ui.button(this,"+ Agregar socio");add.setOnClickListener(v->dialog());r.addView(add);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);r.addView(list);load();setContentView(s);}
 private void load(){list.removeAllViews();Cloud.get(this,"gf_members","select=id,full_name,plan,status,phone&owner_id=eq."+Session.uid(this)+"&order=full_name.asc",(c,b)->{try{JSONArray a=new JSONArray(b);if(a.length()==0)list.addView(Ui.card(this,"Todavía no hay socios","Agregá el primero."));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String id=o.optString("id"),name=o.optString("full_name");TextView t=Ui.card(this,name,o.optString("status")+" · Plan "+o.optString("plan"));t.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(name).setItems(new String[]{"Cambiar estado","Eliminar socio"},(d,w)->{if(w==0){try{JSONObject x=new JSONObject();x.put("status","Activo".equals(o.optString("status"))?"Inactivo":"Activo");Cloud.patch(this,"gf_members","id=eq."+id,x,(cc,bb)->load());}catch(Exception ignored){}}else Cloud.delete(this,"gf_members","id=eq."+id,(cc,bb)->load());}).show());list.addView(t);}}catch(Exception e){list.addView(Ui.card(this,"Error",Cloud.err(b)));}});}
 private void dialog(){LinearLayout box=Ui.page(this);EditText name=Ui.input(this,"Nombre y apellido");box.addView(name);EditText phone=Ui.input(this,"Teléfono (opcional)");box.addView(phone);Spinner plan=Ui.spinner(this,new String[]{"Mensual","Trimestral","Semestral","Libre"});box.addView(plan);new AlertDialog.Builder(this).setTitle("Nuevo socio").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{String n=name.getText().toString().trim();if(n.isEmpty())return;JSONObject o=new JSONObject();o.put("owner_id",Session.uid(this));o.put("full_name",n);o.put("phone",phone.getText().toString().trim());o.put("plan",plan.getSelectedItem().toString());o.put("status","Activo");Cloud.post(this,"gf_members",o,(c,b)->{if(c>=200&&c<300)load();else Toast.makeText(this,Cloud.err(b),Toast.LENGTH_LONG).show();});}catch(Exception ignored){}}).show();}
}
